func actionClass(a Action) string {
	c := "btn"
	if !a.Large {
		c += " sm"
	}
	if a.Primary {
		c += " primary"
	}
	if a.Danger {
		c += " danger"
	}
	return c
}

func actionAttrs(a Action) templ.Attributes {
	attrs := templ.Attributes{
		"id":         a.ID,
		"type":       "submit",
		"form":       a.Form,
		"formaction": a.URL,
		"class":      actionClass(a),
	}
	switch a.Enable {
	case EnableState:
		attrs["data-enable"] = "state"
		attrs["data-state"] = a.State
	case EnableEvery:
		attrs["data-enable"] = "every"
		attrs["data-flag"] = a.Flag
		attrs["data-blocked-title"] = a.Blocked
	default:
		attrs["data-enable"] = "any"
	}
	if a.ConfirmAll != "" {
		attrs["data-confirm-all"] = a.ConfirmAll
	}
	if a.Confirm != "" {
		attrs["data-confirm"] = a.Confirm
	} else {
		attrs["hx-post"] = a.URL
		attrs["hx-swap"] = "none"
	}
	return attrs
}

